def save(path,d):
 p=R/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
def item(title,text,ids=['nccn-patient']):return dict(title=title,text=text,source_ids=ids)
def chap(id,title,intro,items):return dict(id=id,title=title,intro=intro,items=items)
def source(id,title,url):return dict(id=id,title=title,url=url)
NCCN=source('nccn-patient','NCCN Guidelines for Patients: Brain Cancer Glioma, 2026 · patient education reference','https://www.nccn.org/patients/guidelines/content/PDF/brain-gliomas-patient.pdf')
EMA=source('temodal','EMA Temodal product information and patient leaflet','https://www.ema.europa.eu/en/documents/product-information/temodal-epar-product-information_en.pdf')
SAFETY='Use your oncology unit’s written emergency plan. Fever, shivering or suddenly feeling unwell needs urgent advice even on days without chemotherapy. Call 112 or 999 for a new seizure, sudden weakness or speech difficulty, loss of consciousness, severe breathing difficulty or uncontrolled bleeding. If you have an established seizure rescue plan, follow it and its emergency instructions.'
COMMON=[
 chap('glioma-diagnosis','Understanding your particular glioma','Your diagnosis includes the tumour’s cells, molecular findings and behaviour, not just the word brain cancer.',[
 item('The name and location','Gliomas begin in supporting cells of the brain or spinal cord. Astrocytoma, oligodendroglioma and glioblastoma are different diagnoses. A tumour that spread to the brain from another organ is a brain metastasis and is not covered by these glioma regimens. Record the exact integrated diagnosis and where it is located.'),
 item('Grade is not the same as stage','Grade describes features linked to how a tumour behaves. Adult gliomas are usually discussed by their type, grade and molecular findings rather than the stage system used for many other cancers. Grade 4 does not mean cancer has spread through the body. Ask your specialist to explain your own report and any older terminology in the treatment protocol.'),
 item('IDH and 1p/19q','IDH1 or IDH2 changes and loss of parts of chromosomes 1p and 19q help classify particular gliomas. The combination of findings matters: one result should not be read in isolation. These tests are usually performed on tumour tissue. They do not automatically mean a change has been inherited or that relatives need testing.'),
 item('MGMT promoter methylation','MGMT is involved in repairing certain DNA damage. Methylation of its promoter can reduce that repair activity and helps the team discuss the likely benefit of temozolomide in relevant settings. It is not a blood tumour marker, a percentage of tumour left, or an individual survival prediction. Record the reported result and ask how it affects your treatment choice.'),
 item('A useful diagnosis record','Keep the biopsy or operation date, pathology wording, grade, IDH result, 1p/19q result and MGMT result if tested. Mark a result as pending or not applicable rather than assuming it is negative. Ask whether specialist pathology review or further testing would change the plan.')]),
 chap('glioma-tests','Tests and scans: what each one tells you','Safety blood tests, tumour tissue tests and MRI answer different questions.',[
 item('Safety blood tests','A full blood count checks infection-fighting white cells, oxygen-carrying red cells and platelets that help stop bleeding. Kidney and liver tests help assess treatment safety. Attend the regimen’s required tests even when you feel well; a reassuring scan does not replace them. The schedule in this guide separates checks before, during and after treatment.',['nccp','nccn-patient']),
 item('MRI and neurological review','MRI is the main scan used to assess many gliomas. Your team also considers symptoms, strength, movement, speech, memory, daily function and medicines such as steroids. Tell staff before MRI about implants or metal, kidney problems, previous contrast reactions or difficulty lying still. Ask about support if scans make you anxious.'),
 item('Changes on a scan need interpretation','After treatment, inflammation and other treatment effects can resemble tumour growth on MRI. This is sometimes called pseudoprogression. The team may need comparison scans, specialist imaging or further assessment before deciding what a change means. New or worsening symptoms still need prompt review; do not assume they are harmless treatment effects.'),
 item('An individual follow-up timetable','Write the next MRI date, what question it should answer and who will explain the result. Timing depends on your diagnosis, treatment phase and previous findings. General follow-up intervals in an international booklet are not automatically your schedule. These regimens do not require a generic CT chest/abdomen/pelvis or a blood tumour marker before every cycle.'),
 item('Keep results with decisions','Use the passport to distinguish a test being booked, completed and reviewed. Record the agreed next step and whom to call if an appointment or result is missing. Do not alter chemotherapy or steroids yourself in response to a number or scan report.')]),
 chap('glioma-symptoms','Brain symptoms, medicines and when to call','Symptoms may reflect the tumour, swelling, treatment, another medicine or a separate illness.',[
 item('Know your usual symptoms','Write down your usual headache, strength, walking, speech, vision, memory, mood, sleep and seizure pattern before treatment. Note new changes, when they started and how they affect daily tasks. With your permission, a trusted person can help spot changes or record what happened.'),
 item('Urgent neurological changes',SAFETY,['nccp','nccn-patient']),
 item('Steroids need a separate written plan','Steroids may be prescribed to reduce swelling around the tumour. They are not automatically needed for everyone. Ask for the exact dose, time, review date and any taper plan. Do not stop or change them suddenly without advice. Report sleep or mood changes, increased thirst, infection symptoms or muscle weakness and ask which additional checks or protection you need.'),
 item('Seizure medicines and rescue instructions','If prescribed, take seizure medicines on the agreed schedule. Ask what to do after a missed or vomited dose and whom to contact for breakthrough symptoms. Some medicines can affect mood, alertness or interact with treatment. Do not start, stop or switch them yourself. A rescue medicine needs an individual plan and training for whoever may give it.'),
 item('Safety at home and outside','Ask your clinical team about driving, work, bathing, swimming, heights and machinery in light of your symptoms and any seizures. Local medical and licensing rules need individual advice; this guide does not give a universal driving clearance date. Occupational therapy can help adapt daily routines and the home.')]),
 chap('glioma-goals','Your overall treatment plan and choices','Treatment should account for the tumour and the life you want to lead.',[
 item('Understand the sequence','Surgery or biopsy, radiotherapy, chemotherapy and follow-up have different jobs. Ask your team to draw the intended sequence and identify where you are now. Concurrent treatment means treatments overlap; adjuvant treatment follows the main treatment. A change of phase may change the dose, blood tests and support medicines.'),
 item('Agree what treatment is trying to achieve','Ask whether the aim is to control the tumour, delay growth, relieve symptoms, preserve function or a combination of these. Discuss likely benefits, burdens, alternatives and what would prompt a pause or stop. The answer depends on the exact diagnosis, previous treatment and your priorities.'),
 item('Put evidence in context','Clinical trials describe groups of people and may use older pathology names or different schedules. They cannot predict one person’s response or lifespan. Ask how closely the evidence matches your tumour and treatment. No benefit number from one schedule should automatically be applied to another.'),
 item('Discuss options available to you','Ask about appropriate clinical trials, specialist opinions, symptom support and other treatment options. A medicine or device described in an international guide is not automatically licensed, funded or suitable in Ireland. The treating multidisciplinary team explains what is available and relevant.'),
 item('Make room for your priorities','Bring up fatigue, thinking, independence, family time, work, travel and side effects you most want to avoid. Ask for information at a pace and in a format that suits you. You may ask for a trusted person to join the discussion, written notes and time to reconsider decisions.')]),
 chap('glioma-support','Living well, rehabilitation and support','Practical and symptom support can begin alongside anticancer treatment.',[
 item('Thinking, communication and daily tasks','Tell the team about word-finding, attention, memory, reading, vision or planning difficulties. Rehabilitation may include physiotherapy, occupational therapy, speech and language therapy, or neuropsychological support. Written routines, rest breaks and help with medicine organisation can make day-to-day care more manageable.'),
 item('Food, nausea, bowels and energy','Report poor appetite, weight change, vomiting or constipation early. Ask for dietitian help if eating is difficult. Use the prescribed anti-sickness and bowel plan; do not wait until symptoms are severe. Choose activity that is safe for your balance and strength and balance it with rest. Ask about treatable causes of fatigue.',['nccp','nccn-patient']),
 item('Emotional support and carers','Anxiety, low mood, changes in behaviour and uncertainty can affect both patients and carers. Tell the team what has changed and ask for appropriate psychological or social support. Carers may need their own information, practical help and breaks. Agree who the team may share information with.'),
 item('Work, transport and finances','Ask the specialist nurse or social worker about getting to treatment, time off work, benefits, caring responsibilities and support at home. Plan who can help with daily capsules and appointments if your memory, vision or fatigue makes these difficult.'),
 item('Supportive care and future wishes','Supportive and palliative care can help with symptoms and quality of life while active treatment continues. You can discuss future care preferences and who you want involved in decisions at a time that suits you. Ask the team for Irish advice and documentation rather than using legal or hospice rules from a US booklet.'),
 item('Information that works on paper','Keep the printed schedule, current medicine list, tests, contact numbers and emergency instructions together. This handbook can be read in sequence without internet access. The wallet card and optional QR code help others find the regimen information; they do not replace your prescription or emergency plan.')])]
TMZ_AGENT=dict(id='temozolomide',name='Temozolomide',alias='Temodal / generic',type='Oral chemotherapy capsule',mechanism='Damages DNA in tumour cells',explanation='Temozolomide crosses into the brain and creates chemical changes in DNA. If the damage cannot be repaired, a cell may stop dividing or die. Healthy blood-forming cells can also be affected, which helps explain blood-count changes, infection and bleeding risks. Nausea prevention and liver monitoring are important too.',visual=['Capsule swallowed','DNA damaged','Cell growth disrupted'],watch='Report fever, bleeding, persistent vomiting, new breathing symptoms or yellow skin/eyes. Keep blood and liver tests even after capsule days finish.',source_ids=['nccp','temodal'],risks=['Low blood counts, infection and bleeding','Nausea / vomiting and appetite loss','Fatigue, headache and constipation','Liver injury, including delayed injury','PJP and other opportunistic infections','Rash and rare severe skin reactions','Fertility effects and harm to a pregnancy','Rare serious bone-marrow disorders'],symptoms=['Nausea','Fatigue','Constipation'])
PCV_AGENTS=[
 dict(id='lomustine',name='Lomustine',alias='CCNU',type='Oral chemotherapy capsule',mechanism='Damages DNA',explanation='Lomustine damages genetic material so cells cannot divide normally. It can affect cancer cells and healthy bone-marrow cells. Blood counts may fall several weeks after the single dose, so a day without capsules is not a day without risk.',visual=['One scheduled dose','DNA damaged','Delayed blood-count effects possible'],watch='Take only the prescribed Day 1 dose. Do not take it daily or repeat it without oncology instructions. Report fever, bleeding or new breathing symptoms.',source_ids=['nccp'],risks=['Delayed and cumulative low blood counts','Nausea / vomiting','Lung injury','Kidney and liver changes','Rare second cancers and fertility effects'],symptoms=['Nausea','Fatigue']),
 dict(id='procarbazine',name='Procarbazine',alias='Procarbazine capsules',type='Oral chemotherapy capsule',mechanism='Interferes with DNA and cell growth',explanation='Procarbazine is converted in the body into substances that interfere with DNA and cell growth. Healthy blood-forming and digestive tissues can also be affected. It has important interactions with some medicines, alcohol and certain foods, so a pharmacy review and written instructions are essential.',visual=['Capsules on specified days','DNA processes disrupted','Tumour and healthy cells affected'],watch='Follow the exact Days 8–21 calendar and the pharmacist’s medicine, food and alcohol instructions. Report fever, rash or persistent vomiting.',source_ids=['nccp'],risks=['Low blood counts and infection','Nausea / vomiting and appetite changes','Drug, food and alcohol interactions','Liver changes and rash','Fertility effects and rare second cancers'],symptoms=['Nausea','Fatigue']),
 dict(id='vincristine',name='Vincristine',alias='Vincristine infusion',type='Chemotherapy given into a vein',mechanism='Disrupts the machinery used for cell division',explanation='Vincristine interferes with structures that cells use when dividing. It can also affect nerves controlling sensation, strength and bowel movement. This explains why tingling, weakness and constipation need early review even if blood tests are satisfactory.',visual=['Infusion into a vein','Cell division disrupted','Nerves and bowel may be affected'],watch='Report tingling, weakness, walking difficulty or constipation before the next dose. Tell staff immediately if the infusion site stings, burns or swells.',source_ids=['nccp'],risks=['Peripheral and autonomic nerve problems','Constipation and bowel obstruction','Jaw pain and weakness','Tissue injury if medicine leaks outside the vein','Hair thinning / loss'],symptoms=['Tingling / numbness','Constipation','Weakness'])]
CFG={
'00334':dict(title='Temozolomide with radiotherapy, then adjuvant temozolomide',short='Temozolomide + RT',context='Adults with newly diagnosed glioblastoma under NCCP 00334.',purpose='This treatment combines daily temozolomide with radiotherapy, followed by a break and further temozolomide cycles, to help control newly diagnosed glioblastoma. Your team discusses the expected benefit and how it fits after surgery or biopsy.',schedule='Take temozolomide daily throughout six weeks of radiotherapy, including weekends as prescribed. After a four-week break, take temozolomide on Days 1–5 of each 28-day cycle for up to six adjuvant cycles.',concurrent=42,cycles=6,evidence_id='stupp',evidence_url='https://pubmed.ncbi.nlm.nih.gov/15758009/',evidence_title='Stupp EORTC/NCIC trial: radiotherapy with concurrent and adjuvant temozolomide',evidence_intro='A randomised study compared radiotherapy alone with radiotherapy plus concurrent and adjuvant temozolomide in newly diagnosed glioblastoma.',evidence_population='Adults with newly diagnosed glioblastoma in the EORTC/NCIC study.',evidence_text='Adding concurrent and adjuvant temozolomide improved survival in the trial population.',evidence_limits=['This is evidence for the combined treatment strategy; it does not establish a separate benefit for every individual component or an individual survival forecast.','The trial population and older pathology classification do not replace review of the current integrated diagnosis, fitness, MGMT result and patient priorities.']),
'00461':dict(title='Temozolomide with short-course radiotherapy, then adjuvant treatment',short='Temozolomide + short RT',context='Adults older than 65 with newly diagnosed glioblastoma who are not suitable for the standard radiotherapy regimen with temozolomide, under NCCP 00461.',purpose='This plan combines temozolomide with a shorter course of radiotherapy, followed by a break and adjuvant temozolomide, to help control newly diagnosed glioblastoma. NCCP identifies this particular indication as unlicensed; your team explains the evidence, alternatives and local consent process.',schedule='Take temozolomide daily for 21 days during short-course radiotherapy, including weekends as prescribed. After a four-week break, take temozolomide on Days 1–5 of each 28-day cycle for up to six adjuvant cycles.',concurrent=21,cycles=6,evidence_id='perry',evidence_url='https://pubmed.ncbi.nlm.nih.gov/28296618/',evidence_title='Perry trial: short-course radiotherapy with temozolomide in older adults',evidence_intro='A randomised study compared short-course radiotherapy alone with the addition of concurrent and adjuvant temozolomide in older adults with glioblastoma.',evidence_population='Patients aged 65 or older with newly diagnosed glioblastoma in the short-course radiation study.',evidence_text='The addition of temozolomide improved survival in the study population.',evidence_limits=['The study’s age criterion and treatment duration do not replace the current Irish indication and six-cycle adjuvant plan.','An MGMT result helps discuss benefit but does not independently authorise or exclude treatment in this patient guide. Trial results do not predict individual survival.']),
'00342':dict(title='Temozolomide for recurrent or progressive glioma',short='Temozolomide · recurrent glioma',context='Adults with grade III or IV malignant glioma recurring or progressing after standard therapy under NCCP 00342.',purpose='Temozolomide is used to help control a high-grade glioma that has returned or progressed after previous treatment. The team considers previous medicines, current symptoms, scans and your priorities when deciding whether it is suitable.',schedule='Take temozolomide once daily on Days 1–5, then no temozolomide on Days 6–28. Repeat only when your team authorises the next 28-day cycle. The course is reviewed for benefit and toxicity rather than a fixed six-cycle finish.',cycles=0,evidence_id=None,evidence_title='Evidence must match the recurrent setting',evidence_intro='This is the NCCP recurrent or progressive high-grade glioma regimen, not the newly diagnosed chemoradiation schedule.',evidence_population='Adults with recurrent or progressive grade III or IV malignant glioma after standard treatment.',evidence_text='The treatment aim and likely benefit depend on the integrated diagnosis, prior chemotherapy, previous response and current condition.',evidence_limits=['Survival figures from newly diagnosed glioblastoma chemoradiation must not be used as estimates for recurrent disease.','The source schedule is reviewed until progression or unacceptable toxicity; the six-cycle row in its dose table does not establish a universal maximum course.']),
'00379':dict(title='PCV chemotherapy · 42-day cycle',short='PCV · 42 days',context='NCCP 00379: adjuvant treatment of grade II glioma after radiotherapy, or palliative treatment of recurrent high-grade glioma.',purpose='PCV combines procarbazine, lomustine and vincristine. In this 42-day regimen it may follow radiotherapy for grade II glioma or be used to help control recurrent high-grade glioma. Ask which setting and treatment aim apply to you.',cycle=42,cycles=0,evidence_id='rtog9802',evidence_url='https://pubmed.ncbi.nlm.nih.gov/27050206/',evidence_title='PCV evidence depends on the treatment setting',evidence_intro='RTOG 9802 compared radiotherapy alone with radiotherapy followed by PCV in selected patients with grade II glioma.',evidence_population='Higher-risk grade II glioma in RTOG 9802; this is not the recurrent high-grade glioma population.',evidence_text='Adding PCV after radiotherapy improved long-term survival in that study population.',evidence_limits=['RTOG 9802 used an eight-week PCV schedule; it does not provide a schedule-specific efficacy estimate for this six-week regimen.','Its results must not be presented as the expected benefit for recurrent high-grade glioma. No single survival figure is assigned to this card.','The study used historical pathology classification; applicability requires specialist review of the current integrated diagnosis.']),
'00658':dict(title='PCV chemotherapy · 56-day cycle',short='PCV · 56 days',context='NCCP 00658: adjuvant treatment of grade II glioma after radiotherapy.',purpose='This eight-week PCV regimen combines procarbazine, lomustine and vincristine after radiotherapy for grade II glioma. It aims to improve disease control. NCCP describes this indication as unlicensed; the treating team explains the evidence, alternatives and local consent process.',cycle=56,cycles=6,evidence_id='rtog9802',evidence_url='https://pubmed.ncbi.nlm.nih.gov/27050206/',evidence_title='Radiotherapy followed by PCV in selected grade II glioma',evidence_intro='RTOG 9802 compared radiotherapy alone with radiotherapy followed by six eight-week cycles of PCV.',evidence_population='Higher-risk grade II glioma: patients aged 40 or older, or younger adults with less than complete tumour removal.',evidence_text='Adding PCV improved long-term survival in the study population.',evidence_limits=['This evidence does not automatically apply to every grade II glioma or to recurrent high-grade disease.','The study used historical pathology classification; the current integrated diagnosis, risks, expected tolerance and patient priorities guide individual decisions.'])}
