 p=dict(schema_version=1,content_version=V,suite_release=V,patient_layout_release=V,review_status='Source reconciled; independent clinical, pharmacy and patient/PPI review pending',source_checked=DATE,document_revision=DATE,protocol_id=proto['protocol_id'],code=code,protocol_version=md['nccp_version'],title=c['title'],cycle_days=cyc,context_label=c['context'],purpose=c['purpose'],schedule_summary=c['schedule'],scope_heading=c['short'],scope_note=c['context']+' Use the plan matched to your diagnosis and phase; do not borrow another glioma schedule.',service_kind='chemoradiotherapy' if rt else 'chemotherapy',therapy_label='Chemotherapy and radiotherapy in separate phases' if rt else ('Oral chemotherapy' if tmz else 'Two oral medicines and an intravenous medicine'),schedule_kind='glioma_tmz_concurrent_adjuvant' if rt else ('glioma_tmz_recurrent' if tmz else 'glioma_pcv_'+str(cyc)),schedule_label=c['schedule'],indication_text=c['context'],phases_title='Radiotherapy phase → recovery → adjuvant cycles' if rt else 'Treatment days → recovery and tests → review',phases_note='The team confirms each phase and prescription. Do not use the capsule dose or test schedule from a different phase.',medicines_title='How your treatment works',timeline_note='The cycle view shows relative treatment days, not a prediction of when symptoms will peak. Serious symptoms can occur at any time, including rest days.',safety_note=SAFETY,teachback='Can you show the days for each medicine, the current phase, your next blood tests and whom to call for fever, vomiting or new neurological symptoms?',consent_support='Discuss treatment intent, evidence and alternatives; phase-specific schedules; blood and organ monitoring; infection, nausea, fertility and pregnancy precautions; practical support and any unlicensed use. Keep the separate radiotherapy consent and medication plans where applicable.',urgent_extra=SAFETY+' Contact the team promptly for a worsening headache, repeated vomiting, new cough or breathlessness, unusual bruising, yellow skin/eyes or symptoms that prevent drinking. Do not restart held chemotherapy without instructions.',timeline_source_ids=['nccp'],support_source_ids=ids,urgent_source_ids=ids+['nccn-patient'],sources=src,agents=agents,cycle_display='reference-chronology',port_pump=False,longitudinal_mapping=True,passport_visit_note='Record the current phase, every prescribed medicine and treatment day, doses held, safety tests, symptoms, MRI review and the next authorised treatment. A stamp records treatment; it does not authorise the next dose.',anatomy_note='Selected regimen-specific effects use the retained detailed body illustration. Brain symptoms may come from the tumour or treatment; blood, skin and nerve effects are not confined to one point. This is not a prediction or the complete side-effect list.')
 if tmz:
  administration='Take the exact temozolomide capsule strengths and number on your pharmacy label, once daily when prescribed, on an empty stomach. Swallow whole with water; do not open, chew or crush. Ask the pharmacist to write the fasting interval and anti-sickness timing. Different phase doses are not interchangeable.'
  support=[item('Nausea prevention','Temozolomide has moderate-to-high oral emetic potential. Take the prescribed anti-sickness plan before chemotherapy and use rescue medicine as instructed. Ask what to do if nausea prevents taking medicines or fluids.',ids),item('PJP infection prevention',('PJP-prevention medicine is required during temozolomide with radiotherapy in this NCCP regimen. Your team supplies the prescription and decides how long to continue, including if lymphocyte counts remain low. Do not stop it just because radiotherapy has finished.' if rt else 'The team reviews infection and PJP risk, especially with steroids, low lymphocytes or prolonged treatment. A separate prevention prescription may be needed; do not assume the mandatory concurrent-radiotherapy plan automatically applies to this five-day schedule.'),ids),item('Bowels, food and fluids','Anti-sickness medicines and other medicines can worsen constipation. Ask for your bowel plan, and call for persistent vomiting, severe constipation or difficulty drinking. Do not double a dose after vomiting.',ids),item('Steroid and seizure plans','Keep steroids and seizure medicines on their own written schedules if prescribed. They are not routine medicines for every patient, and chemotherapy rest days do not automatically mean stopping them. Ask the pharmacist to check interactions.',['nccp','nccn-patient'])]
