  p['anatomy']=[['brain','Brain / energy','Tumour / treatment','Fatigue or headache may occur. New seizures, sudden weakness, speech difficulty or loss of consciousness need emergency help.',50,5],['mouth','Mouth / eating','Temozolomide','Report mouth soreness, ulcers or reduced intake. Keep gentle mouth care and ask for help before eating or drinking becomes difficult.',50,12.5],['blood','Blood / infection','Temozolomide','Counts can fall after capsule days finish. Fever, sudden illness, bruising or bleeding needs urgent advice; keep all blood tests.',40,22],['lungs','Lungs / PJP','Temozolomide','New cough, fever or breathlessness needs prompt review. Follow the prescribed PJP-prevention plan during chemoradiotherapy.',58,25],['liver','Liver','Temozolomide','Liver injury may appear during or after treatment. Attend liver tests and report yellow skin or eyes, dark urine or unusual itching.',44,34],['bowel','Nausea / bowels','Temozolomide / support medicines','Take anti-sickness medicine as prescribed. Call for repeated vomiting, inability to drink, severe constipation or abdominal pain.',50,44],['skin','Skin / scalp','Radiotherapy / temozolomide' if rt else 'Temozolomide','Follow scalp care during RT; report new rash, blisters or peeling skin. Hair loss and skin irritation depend on the treatment received.' if rt else 'Rash or hair changes may occur. Blistering, peeling skin or a rash with fever needs urgent medical advice.',31,57],['pelvis','Fertility / pregnancy','Temozolomide','Discuss contraception and fertility before starting. Do not breastfeed during treatment. Ask for the written medicine-specific precautions.',50,57]]
